let text = fs.readFileSync(path, 'utf8');
text = text.replace(/function scoreRuns\(cards\) \{[\s\S]*?return 0;\n\}/, `function scoreRuns(cards) {
  const counts = Array(14).fill(0);
  for (const card of cards) counts[RANK_VALUE[cardRank(card)]] += 1;
  for (let length = cards.length; length >= 3; length -= 1) {
    let total = 0;
    for (let start = 1; start <= 13 - length + 1; start += 1) {
      let product = 1;
      let ok = true;
      for (let rank = start; rank < start + length; rank += 1) {
        if (!counts[rank]) {
          ok = false;
          break;
        }
        product *= counts[rank];
      }
      if (ok) total += length * product;
    }
    if (total) return total;
  }
  return 0;
}`);
text = text.replace(/function findRunLengths\(cards\) \{[\s\S]*?return lengths;\n\}/, `function findRunLengths(cards) {
  const counts = Array(14).fill(0);
  for (const card of cards) counts[RANK_VALUE[cardRank(card)]] += 1;
  const lengths = [];
  for (let length = cards.length; length >= 3; length -= 1) {
    let total = 0;
    for (let start = 1; start <= 13 - length + 1; start += 1) {
      let product = 1;
      let ok = true;
      for (let rank = start; rank < start + length; rank += 1) {
        if (!counts[rank]) {
          ok = false;
          break;
        }
        product *= counts[rank];
      }
      if (ok) total += length * product;
    }
    if (total) lengths.push(length);
  }
  return lengths;
}`);
fs.writeFileSync(path, text);
