async function playCard(gameId, seat, card) {
  const game = (await (await fetch(`http://127.0.0.1:3000/api/games/${gameId}?viewer=${seat}`)).json()).game;
  if (game.turn === seat && !(game.legalCards || []).includes(card)) {
    const go = await fetch(`http://127.0.0.1:3000/api/games/${gameId}/actions`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ actionId: crypto.randomUUID(), expectedRevision: game.revision, seat, type: 'go' })
    });
    const goData = await go.json();
    if (!goData.ok) throw new Error(`go failed for ${seat}: ${goData.error}`);
  }
  const fresh = (await (await fetch(`http://127.0.0.1:3000/api/games/${gameId}?viewer=${seat}`)).json()).game;
